import{_ as n,o as s,c as t,a3 as i,j as e,a}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/sekundarstufen/gruppenprozesse-abitur-kurse-algo-markieren.png",l="/bilder/sekundarstufen/gruppenprozesse-abitur-kurse-algo-markieren-ergebnis-reiter-abitur.png",b=JSON.parse('{"title":"Kurse für die Abiturzulassung algorithmisch markieren","description":"","frontmatter":{"title":"Kurse für die Abiturzulassung algorithmisch markieren","source_pageid":391,"source_revision":3379},"headers":[],"relativePath":"zeugnisse/sekundarstufen/kurse-algorithmisch-markieren-gruppenprozesse-abitur.md","filePath":"zeugnisse/sekundarstufen/kurse-algorithmisch-markieren-gruppenprozesse-abitur.md"}'),d={name:"zeugnisse/sekundarstufen/kurse-algorithmisch-markieren-gruppenprozesse-abitur.md"};function o(g,r,h,p,c,m){return s(),t("div",null,[...r[0]||(r[0]=[i('<h1 id="kurse-fur-die-abiturzulassung-algorithmisch-markieren" tabindex="-1">Kurse für die Abiturzulassung algorithmisch markieren <a class="header-anchor" href="#kurse-fur-die-abiturzulassung-algorithmisch-markieren" aria-label="Permalink to &quot;Kurse für die Abiturzulassung algorithmisch markieren&quot;">​</a></h1><p>Lassen Sie nach der Datenübernahme die einzubringenden Kurse markieren. Prüfen Sie Protokoll und mögliche Belegungsfehler vor der Zulassungsentscheidung.</p><p><a href="/bilder/sekundarstufen/gruppenprozesse-abitur-kurse-algo-markieren.png"><img src="'+u+'" alt="Der Gruppenprozess führt die algorithmische Markierung der geholten Leistungsdaten/Kurse für die gesamte Schülermenge aus. Der Schalter Abitur steht erst bei einer exklusiven Auswahl der Q2 zur Verfügung." loading="lazy"></a></p><p><em>Der Gruppenprozess führt die algorithmische Markierung der geholten Leistungsdaten/Kurse für die gesamte Schülermenge aus. Der Schalter Abitur steht erst bei einer exklusiven Auswahl der Q2 zur Verfügung.</em></p><p>Dieser Gruppenprozess bildet die zweite Stufe für die Zulassungsberechnung.</p><p>Wurden die Leistungsdaten bei einem Schüler geholt, individuell im Reiter <em>Abitur</em> oder über den Gruppenprozess <em>Leistungsdaten holen</em>, stehen damit alle Noten für die weitere Berechnung zur Verfügung.</p><p>Der Gruppenprozess <strong>Kurse algorithmisch markieren</strong> versucht, die für die Abiturzulassung zu belegenden Kurse im Reiter <em>Abitur</em> zu markieren. Bei Erfolg sind diese türkis hinterlegt, nicht markierte Kurse haben nach wie vor einen weißen Hintergrund.</p><p>Sind bei der Markierung, welche Kurse einzubringen sind, Alternativen möglich, ist der Algorithmus darauf ausgelegt, die für die Schüler optimalere Variante zu wählen.</p><p>Fallen bei der Überprüfung Belegungsfehler an, werden diese in einer Textdatei ausgegeben. Diese Datei kann ausgedruckt oder abgespeichert werden.</p>',9),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),a("Achtung")]),e("p",null,"Über die Gesamtqualifikation und damit über die Abiturzulassung entscheidet ausschließlich der zentrale Abiturausschuss (ZAA). SchILD-NRW liefert lediglich einen Vorschlag ohne Gewähr für die Beratung des ZAA."),e("p",null,"Der gleiche Vorschlagcharakter ist bei der Schnitt-Optimierung der einzubringenden Kurse anzunehmen.")],-1),i('<p><a href="/bilder/sekundarstufen/gruppenprozesse-abitur-kurse-algo-markieren-ergebnis-reiter-abitur.png"><img src="'+l+'" alt="Das positive Ergebnis der Markierung im Reiter Schüler ➜ Abitur. Markierte Kurse sind türkis hinterlegt." loading="lazy"></a></p><p><em>Das positive Ergebnis der Markierung im Reiter Schüler ➜ Abitur. Markierte Kurse sind türkis hinterlegt.</em></p><p>Zum manuellen Ändern der Kursmarkierung öffnen Sie <strong>Abitur</strong> und doppelklicken auf die Punktzahl. Dadurch wechseln Sie zwischen einem markierten Kurs (türkis) und einem nicht markierten Kurs (weiß).</p><p>Für einen einzelnen Schüler kann der Prozess auch unter dem Karteireiter &quot;Abitur&quot; durch Klicken auf die Schaltfläche <code>Kurse algorithmisch markieren</code> initialisiert werden.</p><p>Hier kann auch per Haken die <em>Überprüfung der Fremdsprache in der Sekundarstufe I</em> von Hand gesetzt werden.</p><p>Es schließt sich hier der Gruppenprozess <strong>Abiturzulassung berechnen</strong> an, der eine korrekte Markierung voraussetzt.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Kurse_algorithmisch_markieren_(Gruppenprozesse_Abitur)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 3379.</p>',8)])])}const f=n(d,[["render",o]]);export{b as __pageData,f as default};
